clean_ch16 = []
seen_ch16 = set()

for word, definition, example in raw_education_words:
    w = word.upper().strip()
    if w in used_words:
        continue
    if w in seen_ch16:
        continue
    seen_ch16.add(w)
    clean_ch16.append({
        "word": w,
        "definition": definition,
        "example": example
    })

print(f"Total raw words prepared: {len(raw_education_words)}")
print(f"Total valid unique Ch16 words: {len(clean_ch16)}")

assert len(clean_ch16) >= 364, f"Need at least 364 words, got {len(clean_ch16)}"

with open("scratch/chapter_16_clean_words.json", "w", encoding="utf-8") as f:
    json.dump(clean_ch16, f, indent=2)

